<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick,watch} from 'vue'
import {request,setToken,selectGroup} from './api'
import StudyPanel from './components/StudyPanel.vue'
import CardDeckPanel from './components/CardDeckPanel.vue'
import StudySummary from './components/StudySummary.vue'
import MemberPermissions from './components/MemberPermissions.vue'
import GroupResources from './components/GroupResources.vue'
import AdvisorFloat from './components/AdvisorFloat.vue'
import AccountShortcuts from './components/AccountShortcuts.vue'
import GroupAccess from './components/GroupAccess.vue'
import NodePanel from './components/NodePanel.vue'
import NotificationPanel from './components/NotificationPanel.vue'
import MailJobsPanel from './components/MailJobsPanel.vue'
import PublicAccessPanel from './components/PublicAccessPanel.vue'
import MathText from './components/MathText.vue'
import GroupMessages from './components/GroupMessages.vue'
const pendingStudyTask=ref(''),pendingPlanManager=ref(false)
function continueStudy(id){pendingStudyTask.value=id;tab.value='learning'}
function openPlanManager(){pendingPlanManager.value=true;pendingStudyTask.value='';tab.value='learning'}
const chatTimeline=ref(null),studyPanel=ref(null),currentStage=ref('尚未加入阶段计划')
const advisorFloat=ref(null),mailPanel=ref(null),unreadCount=ref(0)
const user=ref(null),group=ref(null),members=ref([]),discussions=ref([]),tab=ref('home'),joined=ref(false),error=ref(''),busy=ref(false),modal=ref(''),register=ref(false),advisorQuestion=ref(''),advisorAnswer=ref(''),adminOverview=ref(null),adminRequests=ref([]),adminUsers=ref([])
const form=ref({email:'',password:'',nickname:'',join_key:'',host_name:'我的学习设备',title:'',body:'',avatar_url:'',achievement_suffix:'',oj_provider:'',oj_api_key:'',advisor_provider:'',advisor_api_key:'',advisor_endpoint:'',current_password:'',new_password:'',group_name:'',group_description:'',group_visibility:'PUBLIC'})
const catalog=ref([]),comments=ref({}),replyDrafts=ref({}),advisorConsent=ref(false),advisorSources=ref([]),advisorHistory=ref([])
watch(()=>advisorHistory.value.length,async()=>{await nextTick();if(chatTimeline.value)chatTimeline.value.scrollTop=chatTimeline.value.scrollHeight})
let groupEpoch=0
const groupPages=['group-home','discussion','advisor','members','nodes','learning','group-messages','resources']
const inGroup=computed(()=>groupPages.includes(tab.value)&&joined.value)
const replyTargets=ref({}),messageTarget=ref(null),messageBody=ref('')
const online=computed(()=>members.value.filter(m=>m.online).length)
async function run(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function goHome(){tab.value='home'}
async function exitWorkspace(){try{await studyPanel.value?.saveDraft()}catch(e){error.value=e.message;return}groupEpoch++;joined.value=false;group.value=null;members.value=[];discussions.value=[];comments.value={};replyDrafts.value={};replyTargets.value={};sessionStorage.removeItem('selected-group');tab.value='groups';location.hash='/groups';reloadCatalog()}
function targetReply(post,comment){replyTargets.value[post]={reply_to_user_id:comment.author_id,parent_comment_id:comment.id,nickname:comment.nickname};nextTick(()=>document.getElementById('reply-'+post)?.focus())}
function writeMessage(member){messageTarget.value=member;messageBody.value='';modal.value='message'}
async function sendMessage(){await run(async()=>{await request('group','/group/messages','POST',{recipient_id:messageTarget.value.user_id,body:messageBody.value});messageBody.value='';modal.value='';tab.value='group-messages'})}
function openAccountPage(page){if(page==='settings')populateSettings();tab.value=page;location.hash=pageHash(page).slice(1)}
async function openReply(id){await run(async()=>{const epoch=groupEpoch;await refresh();if(epoch!==groupEpoch)return;const rows=await request('group','/group/discussions/'+id+'/comments');if(epoch!==groupEpoch)return;comments.value[id]=rows;tab.value='discussion';await nextTick();document.getElementById('discussion-'+id)?.scrollIntoView({behavior:'smooth',block:'center'})})}
let routeReady=false,applyingRoute=false
function pageHash(page){return groupPages.includes(page)&&group.value?'#/groups/'+encodeURIComponent(group.value.id)+'/'+(page==='group-home'?'home':page):'#/'+page}
watch(tab,page=>{if(routeReady&&!applyingRoute&&location.hash!==pageHash(page))location.hash=pageHash(page)})
async function accountRoute(){if(!routeReady)return;applyingRoute=true;try{
 const parts=location.hash.slice(2).split('/');const page=parts[0];
 if(page==='groups'&&parts[1]){if(!catalog.value.some(e=>e.id===decodeURIComponent(parts[1]))){try{catalog.value=await request('identity','/community/groups')}catch(e){error.value=e.message}}const entry=catalog.value.find(e=>e.id===decodeURIComponent(parts[1]));if(!entry){error.value='群组不存在或尚未就绪';tab.value='groups';return}
  if(group.value?.id!==entry.id)await chooseGroup(entry);else if(!joined.value)enter();
  const target=parts[2]==='home'||!parts[2]?'group-home':parts[2];if(joined.value&&groupPages.includes(target)){if(target==='advisor'&&tab.value!=='advisor')await openAdvisor();else tab.value=target}
 }else if(['home','groups'].includes(page)){tab.value=page}else if(user.value&&['settings','notifications'].includes(page)){if(page==='settings')populateSettings();tab.value=page}
 }finally{await nextTick();applyingRoute=false}}
async function loadNoticeCount(){const id=user.value?.id;if(!id)return;try{const data=await request('identity','/notifications/unread-count');if(user.value?.id===id)unreadCount.value=data.count}catch{}}
async function authenticate(){await run(async()=>{if(register.value)await request('identity','/auth/register','POST',form.value);const data=await request('identity','/auth/login','POST',form.value);setToken(data.access_token);user.value=data.user;populateSettings();await loadNoticeCount();form.value.password='';modal.value='';accountRoute();if(group.value){await restoreGroup();enter()}})}
async function restoreGroup(){try{await request('group','/group/heartbeat','POST');joined.value=true;await refresh()}catch{joined.value=false;members.value=[];discussions.value=[]}}
async function join(){await run(async()=>{await request('group','/group/join','POST',{join_key:form.value.join_key,host_name:form.value.host_name,nickname:user.value.nickname});joined.value=true;form.value.join_key='';modal.value='';tab.value='group-home';await refresh()})}
async function refresh(){if(!joined.value)return;const epoch=groupEpoch;await request('group','/group/heartbeat','POST');if(epoch!==groupEpoch)return;const [m,d]=await Promise.all([request('group','/group/members'),request('group','/group/discussions')]);if(epoch!==groupEpoch)return;members.value=m;discussions.value=d;const loaded=Object.keys(comments.value).filter(id=>d.some(post=>post.id===id));const updated=await Promise.all(loaded.map(async id=>[id,await request('group','/group/discussions/'+id+'/comments')]));if(epoch===groupEpoch)for(const [id,rows] of updated)comments.value[id]=rows}
async function loadComments(post){await run(async()=>{const epoch=groupEpoch;const rows=await request('group','/group/discussions/'+post+'/comments');if(epoch===groupEpoch)comments.value[post]=rows})}
async function reply(post){await run(async()=>{const epoch=groupEpoch;await request('group','/group/discussions/'+post+'/comments','POST',{body:replyDrafts.value[post],reply_to_user_id:replyTargets.value[post]?.reply_to_user_id,parent_comment_id:replyTargets.value[post]?.parent_comment_id});const rows=await request('group','/group/discussions/'+post+'/comments');if(epoch===groupEpoch){comments.value[post]=rows;replyDrafts.value[post]='';delete replyTargets.value[post]}})}
async function publish(){await run(async()=>{await request('group','/group/discussions','POST',{title:form.value.title,body:form.value.body});form.value.title='';form.value.body='';modal.value='';await refresh()})}
function populateSettings(){if(!user.value)return;form.value.nickname=user.value.nickname;form.value.avatar_url=user.value.avatar_url||'';form.value.achievement_suffix=user.value.achievement_suffix||'';form.value.oj_provider=user.value.integrations?.oj_provider||'';form.value.advisor_provider=user.value.integrations?.advisor_provider||'';form.value.advisor_endpoint=user.value.integrations?.advisor_endpoint||'';form.value.oj_api_key='';form.value.advisor_api_key=''}
async function openAdvisor(){tab.value='advisor';await run(async()=>{const epoch=groupEpoch;const history=await request('identity','/advisor/history?group_id='+encodeURIComponent(group.value.id));if(epoch===groupEpoch)advisorHistory.value=history.slice().reverse()})}
async function clearAdvisor(){await run(async()=>{await request('identity','/advisor/history?group_id='+encodeURIComponent(group.value.id),'DELETE');advisorHistory.value=[];advisorAnswer.value='';advisorSources.value=[]})}
async function saveProfile(){await run(async()=>{user.value=await request('identity','/users/me','PATCH',{nickname:form.value.nickname,avatar_url:form.value.avatar_url});user.value=await request('identity','/cards/profile/suffix','PATCH',{achievement_suffix:form.value.achievement_suffix});populateSettings();modal.value=''})}
async function saveIntegrations(){await run(async()=>{user.value=await request('identity','/users/me/integrations','PUT',{oj_provider:form.value.oj_provider,oj_api_key:form.value.oj_api_key,advisor_provider:form.value.advisor_provider,advisor_api_key:form.value.advisor_api_key,advisor_endpoint:form.value.advisor_endpoint});populateSettings();modal.value=''})}
async function savePassword(){await run(async()=>{await request('identity','/users/me/password','POST',{current_password:form.value.current_password,new_password:form.value.new_password});form.value.current_password='';form.value.new_password='';modal.value=''})}
async function askAdvisor(){await run(async()=>{if(!joined.value)throw new Error('请先加入群组');if(!advisorConsent.value)throw new Error('请确认发送当前群组上下文');const epoch=groupEpoch;const question=advisorQuestion.value.trim();if(!question)throw new Error('请输入问题');const data=await request('identity','/advisor/messages','POST',{group_id:group.value.id,question:question,consent:'share-group-context'});if(epoch===groupEpoch){advisorAnswer.value=data.answer;advisorSources.value=data.sources;advisorHistory.value.push({QUESTION:question,ANSWER:data.answer});if(advisorQuestion.value.trim()===question)advisorQuestion.value=''}})}
async function reloadCatalog(){await run(async()=>{catalog.value=await request('identity','/community/groups')})}
async function createGroup(){await run(async()=>{await request('identity','/community/group-requests','POST',{name:form.value.group_name,description:form.value.group_description,visibility:form.value.group_visibility});form.value.group_name='';form.value.group_description='';form.value.group_visibility='PUBLIC';modal.value='';error.value='群组创建申请已提交，等待服务部署。';await loadAdmin()})}
async function openAdmin(){tab.value='admin';await run(loadAdmin)}
async function loadAdmin(){if(user.value?.role!=='ADMIN')return;adminOverview.value=await request('identity','/admin/overview');adminRequests.value=await request('identity','/admin/group-requests');adminUsers.value=await request('identity','/admin/users');await mailPanel.value?.load()}
async function decideGroupRequest(id,status){await run(async()=>{await request('identity','/admin/group-requests/'+id,'PATCH',{status});await loadAdmin()})}
function enter(){if(!user.value){modal.value='auth';return}if(!joined.value){modal.value='join';return}tab.value='group-home';if(routeReady&&!applyingRoute)location.hash=pageHash('group-home');run(refresh)}
async function chooseGroup(entry){await run(async()=>{await studyPanel.value?.saveDraft();currentStage.value='尚未加入阶段计划';pendingStudyTask.value='';pendingPlanManager.value=false;groupEpoch++;advisorAnswer.value='';advisorSources.value=[];advisorHistory.value=[];advisorQuestion.value='';advisorConsent.value=false;comments.value={};replyDrafts.value={};replyTargets.value={};joined.value=false;members.value=[];discussions.value=[];group.value=null;selectGroup(entry);const info=await request('group','/group');if(info.id!==entry.id)throw new Error('群组目录与服务身份不匹配');group.value=info;if(user.value)await restoreGroup();sessionStorage.setItem('selected-group',entry.id);enter()})}
function logout(){groupEpoch++;advisorHistory.value=[];advisorSources.value=[];advisorAnswer.value='';advisorQuestion.value='';advisorConsent.value=false;comments.value={};replyDrafts.value={};form.value.advisor_api_key='';form.value.oj_api_key='';setToken('');sessionStorage.removeItem('selected-group');user.value=null;unreadCount.value=0;joined.value=false;members.value=[];discussions.value=[];group.value=null;tab.value='groups';history.replaceState(null,'',location.pathname+location.search)}
let interval
onMounted(async()=>{window.addEventListener('hashchange',accountRoute);await run(async()=>{catalog.value=await request('identity','/community/groups');try{user.value=await request('identity','/users/me');populateSettings();await loadNoticeCount()}catch{setToken('')}const last=catalog.value.find(e=>e.id===sessionStorage.getItem('selected-group'));if(last&&user.value){selectGroup(last);const info=await request('group','/group');if(info.id!==last.id)throw new Error('群组服务身份不匹配');group.value=info;await restoreGroup()}});routeReady=true;await accountRoute();interval=setInterval(()=>{if(!document.hidden)loadNoticeCount();if(!document.hidden&&joined.value&&!busy.value)run(refresh)},30000)})
onUnmounted(()=>{clearInterval(interval);window.removeEventListener('hashchange',accountRoute)})
</script>
<template>
 <aside :class="{'group-sidebar':inGroup}" aria-label="主导航"><a class="brand">◈ 算法同行<small>ALGO TOGETHER</small></a><template v-if="inGroup"><div class="workspace-identity"><span class="workspace-emblem">{{group?.name?.slice(0,1)}}</span><strong>{{group?.name}}</strong><small>{{group?.visibility==='PRIVATE'?'私密群组':'公开群组'}} · 独立学习空间</small></div><p class="label compact">群组工作区</p><button :class="{active:tab==='group-home'}" @click="tab='group-home'">⌂ 概览</button><button :class="{active:tab==='learning'}" @click="tab='learning'">✓ 学习</button><button :class="{active:['discussion','group-messages'].includes(tab)}" @click="tab='discussion'">☷ 交流</button><button :class="{active:tab==='resources'}" @click="tab='resources'">▤ 资料</button><button :class="{active:['members','nodes'].includes(tab)}" @click="tab='members'">◎ 成员</button><a class="workspace-exit" href="#/groups" @click.prevent="exitWorkspace">← 退出群组界面</a><small class="exit-hint">返回社区，保留成员资格</small></template><template v-else><p class="label">社区空间</p><button :class="{active:tab==='home'}" @click="goHome()">⌂ 首页</button><button :class="{active:tab==='groups'}" @click="tab='groups';reloadCatalog()">◇ 群组入口</button><button :class="{active:tab==='cards'}" @click="tab='cards'">My Cards</button><button v-if="joined" @click="enter()">→ 继续当前群组</button><button v-if="user?.role==='ADMIN'" :class="{active:tab==='admin'}" @click="openAdmin">管理后台</button></template><div class="aside-note">{{inGroup?'和同伴一起，专注每一步':'找到同伴，开启学习'}}<small>{{inGroup?'讨论 · 学习 · 协作':'算法同行社区'}}</small></div></aside>
 <main :class="{'group-workspace':inGroup}"><header><span>{{inGroup?group?.name:'社区'}} / {{ {'group-messages':'群组消息',resources:'资料',learning:'学习','group-home':'群组首页',home:'首页',groups:'群组入口',discussion:'讨论与复盘',advisor:'机器人顾问',members:'联网成员',nodes:'同步节点',settings:'个人设置',notifications:'消息与申请',admin:'管理后台'}[tab] }}</span><AccountShortcuts :user="user" :group="group" :joined="joined" :unread="unreadCount" @page="openAccountPage" @reply="openReply" @logout="logout" @login="modal='auth'" @changed="loadNoticeCount" /></header>
 <div class="hero" :class="{'workspace-hero':inGroup}"><small>LEARN · SHARE · GROW</small><h1>{{tab==='home'?'每天前进一点，和同伴一起':tab==='learning'?'在这里，推进你的每个目标':tab==='groups'?'找到你的算法同伴':tab==='group-home'?(group?.name||'群组首页'):tab==='discussion'?'把思考分享给同伴':tab==='advisor'?'给思考一点新的启发':tab==='group-messages'?'每一次回应，都找到你':tab==='nodes'?'管理你的同步设备':tab==='settings'?'管理个人资料与连接':'同伴就在这里'}}</h1><p>{{inGroup?'专注当前群组，推进学习、交流思路、回应同伴。':'让每一个独立学习的时刻，都有同伴同行。'}}</p></div>
 <p v-if="error" class="error" role="alert">{{error}}</p>
 <div v-if="inGroup" class="status workspace-switcher"><label>当前群组<select :value="group?.id" :disabled="busy" @change="chooseGroup(catalog.find(e=>e.id===$event.target.value))"><option v-for="entry in catalog" :key="entry.id" :value="entry.id">{{entry.name}}</option></select></label><span>当前阶段：{{currentStage}}</span><span>{{online}} 人在线</span><button class="secondary" :disabled="busy" @click="run(refresh)">同步成员</button></div>
 <section v-if="tab==='home'" class="home-panel"><StudySummary v-if="user" :key="user.id" :catalog="catalog" @enter="chooseGroup"/><div class="card home-welcome"><span class="badge">ALGO TOGETHER</span><h2>从首页开始你的学习旅程</h2><p>选择一个群组，进入它的独立工作区。每个群组都有自己的学习任务、讨论和顾问。</p><div class="home-actions"><button @click="tab='groups';reloadCatalog()">浏览群组</button><button v-if="!user" class="secondary" @click="modal='auth'">开始学习</button></div></div><div class="settings-grid"><article class="card"><h3>群组空间</h3><p>讨论、成员、同步节点和机器人顾问在每个群组内独立运行。</p></article><article class="card"><h3>并行学习</h3><p>在不同群组推进不同目标，各组独立打卡、验证与规划。</p></article></div></section>
 <section v-if="tab==='groups'"><div class="section-head"><h2>可连接的群组</h2><button :disabled="busy" @click="user?modal='create-group':modal='auth'">＋ 创建群组</button></div><div class="group-grid"><article v-for="entry in catalog" :key="entry.id" class="card"><div class="icon">⌘</div><h3>{{entry.name}}</h3><p>{{entry.description}}</p><div class="bottom"><span class="badge">{{joined&&group?.id===entry.id?'已连接':'独立群组服务'}}</span><button :disabled="busy" @click="chooseGroup(entry)">{{joined&&group?.id===entry.id?'进入群组 →':'连接群组 →'}}</button></div></article></div><div v-if="!catalog.length" class="empty">尚未加载群组目录，请检查身份服务是否启动。</div><p class="note">申请提交后由管理员审批；审批通过后由申请人自己在“消息与申请”中一键部署本机群组，部署完成即可查看私密群组加入密钥。</p></section>
 <section v-if="tab==='cards'" class="cards-page"><CardDeckPanel v-if="user"/><div v-else class="card"><h2>登录后管理你的卡包</h2><button @click="modal='auth'">登录 / 注册</button></div></section>
 <section v-if="tab==='group-home'" class="group-home"><span class="badge">{{group?.visibility==='PRIVATE'?'私密群组':'公开群组'}}</span><GroupAccess :key="group?.id" :group="group"/><StudyPanel v-if="user&&joined" :key="user.id+group.id" ref="studyPanel" :group="group" :user="user" :catalog="catalog" compact @continue="continueStudy" @manage-plan="openPlanManager" @stage="currentStage=$event" @plan="advisorFloat?.plan()"/><div class="section-head"><h3>近期组内活动</h3><button class="secondary" @click="tab='discussion'">全部交流</button></div><article v-for="post in discussions.slice(0,3)" :key="post.id" class="card"><h4>{{post.title}}</h4><p>{{post.nickname}} · {{new Date(post.created_at).toLocaleString('zh-CN')}}</p></article></section>
 <section v-if="tab==='discussion'"><button class="secondary" @click="tab='group-messages'">组内私信与消息 →</button><div class="section-head"><div><small class="eyebrow">THINK TOGETHER</small><h2>交流与复盘</h2></div><button v-if="joined" @click="modal='post'">＋ 发布讨论</button></div><p class="muted">正文与回复支持 LaTeX：用 $…$ 输入行内公式，用 $$…$$ 输入独立公式。</p><div v-if="!joined" class="empty">先从群组入口加入一个群组。</div><div v-else-if="!discussions.length" class="empty">分享一个算法疑问，开始第一场讨论。</div><article v-for="post in discussions" :key="post.id" class="card post" :id="'discussion-'+post.id"><span class="muted">{{post.nickname}} · {{new Date(post.created_at).toLocaleString('zh-CN')}}</span><h3>{{post.title}}</h3><MathText :text="post.body"/><button class="secondary" :disabled="busy" @click="loadComments(post.id)">查看 / 刷新回复</button><div class="discussion-replies"><div v-for="comment in comments[post.id]||[]" :key="comment.id" class="comment-item"><div class="comment-heading"><span class="avatar mini">{{comment.nickname?.slice(0,1)}}</span><strong>{{comment.nickname}}</strong><span v-if="comment.recipient_nickname" class="muted">→ {{comment.recipient_nickname}}</span><small class="muted">{{new Date(comment.created_at).toLocaleString('zh-CN')}}</small></div><MathText :text="comment.body"/><button v-if="comment.author_id!==user?.id" class="reply-person" @click="targetReply(post.id,comment)">回复 {{comment.nickname}}</button></div></div><form class="reply-composer" @submit.prevent="reply(post.id)"><div v-if="replyTargets[post.id]" class="reply-target">正在回复 {{replyTargets[post.id].nickname}} <button type="button" class="secondary" @click="delete replyTargets[post.id]">取消定向回复</button></div><label>回复同伴<textarea :id="'reply-'+post.id" v-model="replyDrafts[post.id]" maxlength="5000" required placeholder="写下你的思路，支持 $公式$ 与 $$公式$$"></textarea></label><details v-if="replyDrafts[post.id]" class="formula-preview"><summary>预览公式</summary><MathText :text="replyDrafts[post.id]"/></details><button :disabled="busy">发送回复</button></form></article></section>
 <section v-if="tab==='members'"><MemberPermissions :key="group.id" :group="group" :user="user" @changed="run(refresh)"/><button class="secondary" @click="tab='nodes'">同步节点与设备 →</button><h2>联网成员</h2><div v-if="!joined" class="empty">加入群组后查看同伴。</div><div v-for="member in members" :key="member.user_id" class="member"><span class="avatar">{{member.nickname.slice(0,1)}}</span><div><strong>{{member.nickname}}</strong><small>{{member.host_name}}</small></div><button v-if="member.user_id!==user?.id" class="secondary" @click="writeMessage(member)">发消息</button><span :class="['presence',{offline:!member.online}]">{{member.online?'● 在线':'● 离线'}}</span></div><p class="note">30 秒心跳同步，90 秒未收到心跳后显示离线。</p></section>
 <section v-if="tab==='advisor'" class="advisor-studio"><div class="advisor-chat"><div class="section-head"><div><small class="eyebrow">YOUR ALGORITHM COMPANION</small><h2>群组机器人顾问</h2></div><button class="secondary" :disabled="busy" @click="clearAdvisor">清空会话</button></div><div ref="chatTimeline" class="chat-timeline" role="log" aria-label="顾问会话"><div v-if="!advisorHistory.length" class="advisor-empty"><div class="advisor-orb">✦</div><h3>把卡住的思路，说给顾问听</h3><p>从一个边界、一个复杂度问题，或一段复盘开始。</p><div class="advisor-prompts"><button class="secondary" @click="advisorQuestion='帮我解释二分查找的不变量，并给出边界测试'">理解不变量</button><button class="secondary" @click="advisorQuestion='如何分析时间复杂度？请用一个例子引导我'">分析复杂度</button><button class="secondary" @click="advisorFloat?.plan()">规划明日目标</button></div></div><div v-for="(turn,i) in advisorHistory" :key="i" class="chat-turn"><div class="chat-message from-user"><small>我</small><MathText :text="turn.QUESTION"/></div><div class="chat-message from-advisor"><small>✦ 算法顾问</small><MathText :text="turn.ANSWER"/></div></div><div v-if="busy" class="chat-thinking" role="status">顾问正在整理思路…</div></div><form class="chat-composer" @submit.prevent="askAdvisor"><label>向顾问提问<textarea v-model="advisorQuestion" maxlength="4000" placeholder="描述你的问题，公式也可以直接输入…"></textarea></label><label class="consent"><input type="checkbox" v-model="advisorConsent"><span>允许发送问题、我的近期会话与本群组最近 10 条讨论到已配置模型</span></label><div class="section-head"><small class="muted">只在当前群组延续会话</small><button :disabled="busy||!joined||!advisorConsent||!advisorQuestion.trim()">{{busy?'思考中…':'发送问题 ↗'}}</button></div></form></div><div class="advisor-context"><article class="card"><span class="badge">{{group?.name}}</span><h3>一点提示，一步进展</h3><p>先说明你已经尝试过什么，让顾问帮你找到下一步，而不止是一个答案。</p><ul><li>解释思路与边界</li><li>分析复杂度与取舍</li><li>结合打卡规划明日</li></ul><button class="secondary" @click="tab='learning'">查看本群组学习任务 →</button></article><article class="card"><h3>模型连接</h3><p>{{user?.integrations?.advisor_key_configured?'已保存模型配置。会话仅自己可见。':'先在个人设置中填写模型接口地址、名称和密钥。'}}</p><button class="secondary" @click="openAccountPage('settings')">个人设置</button><details v-if="advisorSources.length" class="advisor-sources"><summary>本次参考讨论（{{advisorSources.length}}）</summary><p v-for="source in advisorSources" :key="source.id">{{source.title}}</p></details></article></div></section>
 <section v-if="tab==='settings'"><h2>个人设置</h2><p class="note">成就后缀会显示在用户名旁边，可随时清空。</p><label>成就后缀（可选）<input v-model="form.achievement_suffix" maxlength="80" placeholder="例如：· 二分探索者"></label><div class="settings-grid"><article class="card"><h3>资料与头像</h3><label>昵称<input v-model="form.nickname"></label><label>头像地址<input v-model="form.avatar_url" placeholder="https://... 或本地图片地址"></label><button @click="saveProfile">保存资料</button></article><article class="card"><h3>修改密码</h3><label>当前密码<input v-model="form.current_password" type="password"></label><label>新密码<input v-model="form.new_password" type="password" minlength="8"></label><button @click="savePassword">更新密码</button></article><article class="card"><h3>服务连接</h3><label>OJ 平台<select v-model="form.oj_provider"><option value="">未配置</option><option>Codeforces</option><option>AtCoder</option><option>Luogu</option></select></label><label>OJ API 密钥<input v-model="form.oj_api_key" type="password"></label><label>模型接口地址<input v-model="form.advisor_endpoint" type="url" placeholder="https://服务地址/v1/chat/completions"></label><label>顾问模型名称<input v-model="form.advisor_provider" placeholder="填写服务支持的模型名称"></label><label>顾问 API 密钥（留空保留已保存密钥）<input v-model="form.advisor_api_key" type="password"></label><button @click="saveIntegrations">保存连接设置</button></article></div></section>
 <NotificationPanel v-if="tab==='notifications'&&user" :key="user.id" @changed="loadNoticeCount" />
<StudyPanel v-if="tab=== 'learning'&&user&&joined" ref="studyPanel" :key="user.id+group.id+pendingPlanManager" :group="group" :user="user" :catalog="catalog" :initial-task="pendingStudyTask" :open-plan-manager="pendingPlanManager" @opened="pendingStudyTask='';pendingPlanManager=false" @stage="currentStage=$event" @plan="advisorFloat?.plan()" @manage-plan="pendingPlanManager=false" @help="run(refresh)"/><GroupResources v-if="tab==='resources'&&joined" :key="group.id" :group="group"/>
 <GroupMessages v-if="tab==='group-messages'&&joined" :key="group.id" :user="user" @reply="openReply" @message="writeMessage"/>
 <NodePanel v-if="tab==='nodes'" :key="group?.id||'none'" :joined="joined" />
 <section v-if="tab==='admin'"><div class="section-head"><h2>管理后台</h2><button :disabled="busy" @click="run(loadAdmin)">刷新</button></div><div class="admin-grid"><article class="card">用户 {{adminOverview?.users??'—'}}</article><article class="card">管理员 {{adminOverview?.admins??'—'}}</article><article class="card">群组 {{adminOverview?.configured_groups??'—'}}</article><article class="card">待处理 {{adminOverview?.pending_group_requests??'—'}}</article></div><PublicAccessPanel /><MailJobsPanel ref="mailPanel" /><h3>群组创建申请</h3><div class="admin-scroll-list" role="region" aria-label="群组申请滚动列表" tabindex="0"><div v-if="!adminRequests.length" class="empty">暂无申请</div><div v-for="item in adminRequests" :key="item.ID" class="member"><div><strong>{{item.NAME}}</strong><small>{{item.DESCRIPTION}}</small></div><span class="badge">{{item.STATUS}}</span><template v-if="item.STATUS==='PENDING'"><button :disabled="busy" @click="decideGroupRequest(item.ID,'APPROVED')">批准</button><button class="secondary" :disabled="busy" @click="decideGroupRequest(item.ID,'REJECTED')">驳回</button></template></div></div><h3>账号列表</h3><div class="admin-scroll-list" role="region" aria-label="账号滚动列表" tabindex="0"><div v-for="item in adminUsers" :key="item.ID" class="member"><div><strong>{{item.NICKNAME}}</strong><small>{{item.EMAIL}}</small></div><span class="badge">{{item.ROLE}}</span></div></div></section><footer>算法同行 · 目标驱动的算法学习社区</footer></main><AdvisorFloat ref="advisorFloat" :user="user" :group="group" :joined="inGroup" />
 <div v-if="modal" class="overlay"><div class="dialog" role="dialog" aria-modal="true"><div class="section-head"><h2>{{modal==='auth'?(register?'创建学习账号':'欢迎回来'):modal==='join'?'密钥加入群组':modal==='post'?'发布讨论':modal==='message'?'发送成员消息':'申请创建群组'}}</h2><button class="secondary" @click="modal=''">✕</button></div><form @submit.prevent="modal==='auth'?authenticate():modal==='join'?join():modal==='post'?publish():modal==='message'?sendMessage():createGroup()"><template v-if="modal==='auth'"><label>邮箱<input v-model="form.email" type="email" required></label><label>密码<input v-model="form.password" type="password" minlength="8" required></label><label v-if="register">昵称<input v-model="form.nickname" maxlength="40" required></label><button type="button" class="secondary" @click="register=!register">{{register?'已有账号？登录':'还没有账号？注册'}}</button></template><template v-if="modal==='join'"><label v-if="group?.visibility!=='PUBLIC'">群主分享的联网密钥<input v-model="form.join_key" type="password" minlength="16" required></label><label>设备名称<input v-model="form.host_name" maxlength="80" required></label></template><template v-if="modal==='post'"><label>标题<input v-model="form.title" maxlength="100" required></label><label>内容<textarea v-model="form.body" maxlength="20000" required></textarea></label></template><template v-if="modal==='message'"><p>发送给 <strong>{{messageTarget?.nickname}}</strong> · 当前群组</p><label>消息内容<textarea v-model="messageBody" maxlength="5000" required placeholder="支持 LaTeX 公式，仅你与收件人可见"></textarea></label><MathText v-if="messageBody" :text="messageBody"/></template><template v-if="modal==='create-group'"><label>群组名称<input v-model="form.group_name" maxlength="60" required></label><label>群组简介<textarea v-model="form.group_description" maxlength="500" required></textarea></label><label>群组类型<select v-model="form.group_visibility"><option value="PUBLIC">公开群组 · 无需加入密钥</option><option value="PRIVATE">私密群组 · 需要加入密钥</option></select></label><p class="note">公开群组部署后可直接进入；私密群组部署完成后，申请人可在自己的“消息与申请”中查看和复制加入密钥。管理员只负责审批。</p></template><p v-if="error" class="error">{{error}}</p><button class="submit" :disabled="busy">{{busy?'处理中…':'确认'}}</button></form></div></div>
</template>
